sys_script_client.script:
//SN5106 - Dynamic Prioritization
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
  if (isLoading) return;


  var select = g_form.getControl('expected_value');
  var displayValue = '';
  if (select) {
    for (var i = 0; i < select.options.length; i++) {
      if (select.options[i].value == newValue) {
        displayValue = select.options[i].text;
        break;
      }
    }
  }
  g_form.setValue('expected_display', displayValue);
}
